SELECT id, symbol, status, started_at, last_evidence_at, anchor_entry_price, best_entry_price, evidence_count, buy_count, watch_count, neutral_count, bearish_count, evidence_score, opportunity_health, five_minute_decision, one_hour_decision, execution_source, recommended_position_percent, decision_code, latest_signal_id, executed_at, updated_at FROM crypto_ai.execution_opportunity WHERE (symbol='EGLDUSDT' AND started_at <= '2026-10-11 22:40:04' AND last_evidence_at >= '2026-10-11 20:50:00') OR (symbol='XRPUSDT' AND started_at <= '2026-10-12 02:35:03' AND last_evidence_at >= '2026-10-12 02:30:00') OR (symbol='DOGEUSDT' AND started_at <= '2026-10-12 04:02:05' AND last_evidence_at >= '2026-10-12 03:55:00') OR (symbol='SHIBUSDT' AND started_at <= '2026-10-12 06:36:03' AND last_evidence_at >= '2026-10-12 06:30:00') OR (symbol='ACEUSDT' AND started_at <= '2026-10-12 09:57:05' AND last_evidence_at >= '2026-10-12 09:50:00') ORDER BY symbol, started_at LIMIT 60;